use vstd::prelude::*;

verus! {
    /// Swap the first and last elements of a non‐empty vector in place.
    /// 
    /// Requires:
    ///   - a.len() >= 1
    /// Ensures (old is the pre‐state of `a`):
    ///   - length is unchanged
    ///   - new first element == old last element
    ///   - new last element  == old first element
    ///   - all interior elements are unchanged
    fn swap_first_and_last(a: &mut Vec<i32>)
        requires
            a.len() >= 1,
        ensures
            |old: Vec<i32>|
                old.len() == a.len() &&
                // new first == old last
                a[0] == old[old.len() - 1] &&
                // new last == old first
                a[a.len() - 1] == old[0] &&
                // all elements in between are unchanged
                forall(|i: usize| 1 <= i && i + 1 < a.len() ==> a[i] == old[i]),
    {
        let len = a.len();
        // Since len >= 1, both indices 0 and len-1 are in bounds.
        let tmp = a[0];
        a[0] = a[len - 1];
        a[len - 1] = tmp;
    }
}

